CREATE DATABASE IF NOT EXISTS rifas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rifas;
CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,senha VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rifas(id INT AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(180) NOT NULL,descricao TEXT,imagem VARCHAR(500),preco DECIMAL(10,2) NOT NULL,total_numeros INT NOT NULL DEFAULT 100,tipo ENUM('selecionavel','aleatoria') NOT NULL DEFAULT 'selecionavel',status ENUM('ativa','pausada','encerrada') NOT NULL DEFAULT 'ativa',data_sorteio DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pedidos(id INT AUTO_INCREMENT PRIMARY KEY,rifa_id INT NOT NULL,nome VARCHAR(150) NOT NULL,telefone VARCHAR(30),email VARCHAR(160),quantidade INT NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('pendente','pago','cancelado') DEFAULT 'pendente',codigo VARCHAR(32) UNIQUE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(rifa_id) REFERENCES rifas(id) ON DELETE CASCADE);
CREATE TABLE bilhetes(id BIGINT AUTO_INCREMENT PRIMARY KEY,rifa_id INT NOT NULL,pedido_id INT NOT NULL,numero INT NOT NULL,status ENUM('reservado','pago','cancelado') DEFAULT 'reservado',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uniq_numero(rifa_id,numero),FOREIGN KEY(rifa_id) REFERENCES rifas(id) ON DELETE CASCADE,FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE);
